CREATE OR REPLACE FUNCTION public.attach_confirmed_customer_invoice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_drafts;q jsonb;provider jsonb;bill jsonb;inv uuid;service text;a public.provider_facility_agreement_versions; BEGIN
IF NEW.customer_quote_id IS NULL AND NEW.customer_quote_draft_id IS NULL THEN RETURN NEW;END IF;
SELECT * INTO d FROM public.trip_drafts WHERE id=NEW.customer_quote_draft_id AND user_id=NEW.actor_user_id AND workspace_id=NEW.workspace_id AND submitted_trip_id IS NULL FOR UPDATE;q:=d.customer_quote_history->-1;
IF d.id IS NULL OR (q->>'id')::uuid IS DISTINCT FROM NEW.customer_quote_id OR EXISTS(SELECT 1 FROM public.trip_invoice_documents WHERE quote_id=NEW.customer_quote_id) THEN RAISE EXCEPTION 'Confirmed quote unavailable';END IF;
service:=CASE WHEN NEW.trip_kind='medical_delivery' THEN 'medical_delivery' WHEN NEW.transport_type='gurney' THEN 'stretcher' ELSE NEW.transport_type END;
IF q->'trip'->>'service' IS DISTINCT FROM service OR q->'trip'->>'pickupDate' IS DISTINCT FROM NEW.pickup_date::text OR left(q->'trip'->>'pickupTime',5) IS DISTINCT FROM left(NEW.pickup_time::text,5) OR (q->'trip'->>'roundTrip')::boolean IS DISTINCT FROM NEW.round_trip OR q->>'formFingerprint' IS DISTINCT FROM encode(sha256(convert_to(jsonb_build_object('pickupAddress',NEW.pickup_address,'pickupCity',NEW.pickup_city,'dropoffAddress',NEW.dropoff_address,'dropoffCity',NEW.dropoff_city,'patientWorkspaceId',NEW.patient_workspace_id,'additionalStops',NEW.additional_stops,'returnDate',NEW.return_date,'returnPickupTime',NEW.return_pickup_time)::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'Trip changed; confirm a new quote';END IF;
IF NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=NEW.workspace_id AND m.user_id=NEW.actor_user_id AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL) THEN RAISE EXCEPTION 'Invoice management unavailable';END IF;
IF q->>'facilityAgreementId' IS NOT NULL THEN
SELECT * INTO a FROM public.provider_facility_agreement_versions WHERE id=(q->>'facilityAgreementId')::uuid AND facility_workspace_id=NEW.workspace_id AND facility_confirmed_by=NEW.actor_user_id AND scope_fingerprint=q->>'formFingerprint';
IF a.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.account_business_connections WHERE id=a.connection_id AND active) OR NEW.selected_provider_workspace_id IS DISTINCT FROM a.provider_workspace_id OR (q->>'totalCents')::integer<>a.approved_total_cents THEN RAISE EXCEPTION 'Facility agreement unavailable';END IF;
SELECT jsonb_build_object('name',display_name) INTO provider FROM public.workspaces WHERE id=a.provider_workspace_id AND status='active' AND NOT is_test_account;IF provider IS NULL THEN RAISE EXCEPTION 'Provider unavailable';END IF;
SELECT jsonb_build_object('name',display_name,'workspaceId',id,'responsiblePayerWorkspaceId',a.responsible_payer_workspace_id) INTO bill FROM public.workspaces WHERE id=a.bill_to_workspace_id;
INSERT INTO public.trip_invoice_documents(request_id,provider_workspace_id,patient_workspace_id,billed_workspace_id,quote_id,quote_snapshot,provider_snapshot,bill_to_snapshot,total_cents,created_by,person_mfn_id,workspace_mfn_id,facility_agreement_id,responsible_payer_workspace_id) VALUES(NEW.id,a.provider_workspace_id,NEW.patient_workspace_id,a.bill_to_workspace_id,NEW.customer_quote_id,q,provider,bill,a.approved_total_cents,NEW.actor_user_id,NEW.creator_person_mfn_id,NEW.originating_workspace_mfn_id,a.id,a.responsible_payer_workspace_id) RETURNING id INTO inv;
ELSE
IF NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=NEW.workspace_id AND account_type='provider') THEN RAISE EXCEPTION 'Approved facility agreement required';END IF;
SELECT jsonb_build_object('name',w.display_name,'phone',CASE WHEN p.trip_dispatch_phone_designated THEN p.trip_dispatch_phone END) INTO provider FROM public.workspaces w LEFT JOIN public.provider_network_profiles p ON p.workspace_id=w.id WHERE w.id=NEW.workspace_id;
IF NEW.patient_workspace_id IS NOT NULL THEN SELECT jsonb_build_object('name',w.display_name,'email',u.email,'userId',u.id) INTO bill FROM public.workspaces w JOIN public.workspace_members m ON m.workspace_id=w.id JOIN auth.users u ON u.id=m.user_id WHERE w.id=NEW.patient_workspace_id AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND u.email_confirmed_at IS NOT NULL ORDER BY m.created_at LIMIT 1;ELSE bill:=jsonb_build_object('name',trim(coalesce(NEW.trip_billing_first_name,NEW.patient_first_name)||' '||coalesce(NEW.trip_billing_last_name,NEW.patient_last_name)),'email',coalesce(NEW.trip_billing_email,NEW.patient_email));END IF;
INSERT INTO public.trip_invoice_documents(request_id,provider_workspace_id,patient_workspace_id,quote_id,quote_snapshot,provider_snapshot,bill_to_snapshot,total_cents,created_by,person_mfn_id,workspace_mfn_id) VALUES(NEW.id,NEW.workspace_id,NEW.patient_workspace_id,NEW.customer_quote_id,q,provider,bill,(q->>'totalCents')::integer,NEW.actor_user_id,NEW.creator_person_mfn_id,NEW.originating_workspace_mfn_id) RETURNING id INTO inv;
END IF;
INSERT INTO public.trip_invoice_events(invoice_id,action,actor_id,person_mfn_id,details) VALUES(inv,'invoice_ready',NEW.actor_user_id,NEW.creator_person_mfn_id,jsonb_build_object('quoteId',NEW.customer_quote_id,'agreementId',a.id,'agreementVersion',a.version,'source',CASE WHEN a.id IS NULL THEN 'provider_owned' ELSE 'facility_agreement' END));RETURN NEW;END $$;